use std :: fs ; use std :: io :: { BufRead , BufReader } ; use std :: path :: PathBuf ; use std :: process :: Stdio ; use anyhow :: { Context , Result } ; use clap :: CommandFactory ; use clap_complete :: generate ; use clap_complete :: shells :: Zsh ; use include_dir :: { Dir , include_dir } ; use crate :: cli :: Cli ; use std :: io :: Write ; use std :: sync :: { LazyLock , Mutex } ; use super :: * ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; # [doc = " Generates the ZSH theme for Forge"] pub fn generate_zsh_theme () -> Result < String > { let mut content = super :: normalize_script (include_str ! ("../../../../shell-plugin/forge.theme.zsh")) ; content . push_str ("\n_FORGE_THEME_LOADED=$(date +%s)\n") ; Ok (content) }